sys_script_include.script:
var EventRegistrationUtils  = Class.create();
EventRegistrationUtils .prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	registerAttendee: function() {
		var attendeeId = this.getParameter('sysparm_attendeeID');
        var firstName = this.getParameter('sysparm_firstName');
        var lastName = this.getParameter('sysparm_lastName');
        var email = this.getParameter('sysparm_email');
        var contactNumber = this.getParameter('sysparm_contactNumber');
        var eventID = this.getParameter('sysparm_eventID');


        var attendeeGR = new GlideRecord('x_1610434_event_0_attendee'); // Replace with the 
        attendeeGR.addQuery('sys_id',attendeeId);
		attendeeGR.query();
		while(attendeeGR.next()){
        attendeeGR.setValue('first_name', firstName);
        attendeeGR.setValue('last_name', lastName);
        attendeeGR.setValue('email', email);
        attendeeGR.setValue('contact_number', contactNumber);
        attendeeGR.setValue('event_id', eventID);
		attendeeGR.update();
		}

        return 'success';
    },

    type: 'EventRegistrationUtils '
});
